using System;using System.IO;using System.Threading;using OsuLegacy;
class DifficultyTests {
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}static void Wait(Func<bool> ready){var timer=DateTime.UtcNow;while(!ready()){if((DateTime.UtcNow-timer).TotalMilliseconds>10000)throw new Exception("Difficulty worker timeout");Thread.Sleep(5);}}
 static string Map(int mode,int count,int spacing){string s="osu file format v14\n[General]\nAudioFilename: missing.mp3\nMode: "+mode+"\n[Metadata]\nTitle: Difficulty fixture\nVersion: Test\n[Difficulty]\nHPDrainRate:5\nCircleSize:4\nOverallDifficulty:7\nApproachRate:8\nSliderMultiplier:1.4\nSliderTickRate:1\n[TimingPoints]\n0,500,4,2,0,100,1,0\n[HitObjects]\n";for(int i=0;i<count;i++){int x=64+(i%4)*128;string obj=x+","+(64+i%3*128)+","+(1000+i*spacing)+",";if(mode==3 && i%3==0)s+=obj+"128,0,"+(1300+i*spacing)+":0:0:0:0:\n";else s+=obj+"1,"+(mode==1 && i%2==0?2:0)+",0:0:0:0:\n";}return s;}
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"osu-difficulty-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
 string path=Path.Combine(root,"fixture.osu");double[] normal=new double[4];for(int mode=0;mode<4;mode++){File.WriteAllText(path,Map(mode,120,150));var timer=DateTime.UtcNow;normal[mode]=LocalDifficulty.Calculate(path,mode,null,null);Check(normal[mode]>0 && !double.IsNaN(normal[mode]),"Finite native rating in mode "+mode);Console.WriteLine("Difficulty mode {0}: {1:F8}, host {2} ms",mode,normal[mode],(DateTime.UtcNow-timer).TotalMilliseconds);var mods=new LegacyModState();mods.Toggle(mods.All.Find(delegate(LegacyMod m){return m.Acronym=="DT";}));double faster=LocalDifficulty.Calculate(path,mode,new ModSettings(mods,mode),null);Check(faster>normal[mode],"DT increases strain in mode "+mode);File.WriteAllText(path,Map(mode,0,150));Check(LocalDifficulty.Calculate(path,mode,null,null)==0,"Empty map gives zero in mode "+mode);}
 File.WriteAllText(path,Map(0,120,150));for(int mode=1;mode<4;mode++)Check(LocalDifficulty.Calculate(path,mode,null,null)>0,"Standard conversion rated in mode "+mode);
 File.WriteAllText(path,Map(0,0,150));File.AppendAllText(path,"64,64,1000,2,0,B|128:128|256:64,2,240\n320,192,2200,1,0,0:0:0:0:\n256,192,2500,8,0,3500\n64,64,3900,1,0,0:0:0:0:\n");Check(LocalDifficulty.Calculate(path,0,null,null)>0,"Sliders, repeats, ticks and spinner transitions rated");bool cancelled=false;try{LocalDifficulty.Calculate(path,0,null,delegate{throw new OperationCanceledException();});}catch(OperationCanceledException){cancelled=true;}Check(cancelled && Beatmap.LoadCheckpoint==null,"Cancellation releases thread-local parser callback");
 File.WriteAllText(path,Map(0,120,150));var cache=new DifficultyCache(root);int caller=Thread.CurrentThread.ManagedThreadId,worker=caller;cache.WorkerStarted=delegate{worker=Thread.CurrentThread.ManagedThreadId;};Check(cache.Request(path,0,null)<0,"Uncached request returns immediately");Wait(delegate{return cache.Revision>0;});double rating=cache.Request(path,0,null);Check(rating>0 && cache.Calculations==1 && worker!=caller,"Rating calculated once off UI thread");for(int i=0;i<1000;i++)cache.Request(path,0,null);Check(cache.Calculations==1,"Repeated draws do not recalculate");var restored=new DifficultyCache(root);restored.Request(path,0,null);Wait(delegate{return restored.Revision>0;});Check(restored.Request(path,0,null)==rating && restored.Calculations==0 && restored.Hits==1,"Restart reads persistent rating without parsing notes");
 File.WriteAllText(path,Map(0,150,100));var changed=new DifficultyCache(root);changed.Request(path,0,null);Wait(delegate{return changed.Revision>0;});Check(changed.Calculations==1 && changed.Request(path,0,null)!=rating,"Modified file invalidates disk cache");
 var dt=new LegacyModState();dt.Toggle(dt.All.Find(delegate(LegacyMod m){return m.Acronym=="DT";}));int revision=changed.Revision;changed.Request(path,0,new ModSettings(dt,0));Wait(delegate{return changed.Revision>revision;});Check(changed.Calculations==2,"Relevant mods have independent cached values");
 var gate=new ManualResetEvent(false);var started=new ManualResetEvent(false);var paused=new DifficultyCache(root);paused.WorkerCheckpoint=delegate{started.Set();gate.WaitOne();};paused.Request(path,0,null);Check(started.WaitOne(2000),"Worker reaches gameplay pause checkpoint");Check(paused.Revision==0,"Paused worker publishes no premature rating");gate.Set();Wait(delegate{return paused.Revision>0;});
 Console.WriteLine("PASS: "+checks+" local difficulty, modes/converts, rate mods, cancellation, worker pause and persistent-cache checks");
 }finally{Directory.Delete(root,true);}}
}
